package net.civeira.phylax.features.document.templateversion.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.document.templateversion.application.visibility.TemplateVersionVisibilityCheck;

public class TenantAccesible {

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param filter
   */
  public void filterVisibles(@Observes TemplateVersionVisibilityCheck filter) {
    Actor actor = filter.getActor();
    if (!(actor.hasScope("platform:global_access"))) {
      filter.peek(fl -> fl.setTemplateTenantAccesible(actor.getTenant().orElse(null)));
    }
  }
}
